    static BigDecimal calculateShipping(int zone, double actualWeight,
                                         int lengthIn, int widthIn, int heightIn) {

golden_completion:
    BigDecimal baseRate = ZONE_RATES.getOrDefault(zone, new BigDecimal("18.00"));
    int dimWeight = (int) Math.ceil((double)(lengthIn * widthIn * heightIn) / 139.0);
    double billableWeight = Math.max(actualWeight, dimWeight);
    BigDecimal surcharge;
    if (billableWeight <= 5.0) {
        surcharge = BigDecimal.ZERO;
    } else if (billableWeight <= 20.0) {
        surcharge = new BigDecimal("3.00");
    } else if (billableWeight <= 50.0) {
        surcharge = new BigDecimal("8.00");
    } else {
        surcharge = new BigDecimal("15.00");
    }
    BigDecimal total = baseRate.add(surcharge).setScale(2, RoundingMode.HALF_UP);
    BigDecimal minimum = new BigDecimal("7.00");
    return total.compareTo(minimum) < 0 ? minimum : total;
}

