    // Rules:
    //  1. Return window: 0-14 days: no fee, 15-30 days: 15% restocking fee,
    //     31+ days: return DENIED
    //  2. Restocking fee calculated on item price (not including tax)
    //  3. Refund amount = price - restocking fee (rounded to 2 decimal places)
    //  4. Each return logged as "RETURN:<orderId>:<APPROVED|DENIED>:<refundAmount>"
    //     For denied returns, refundAmount is "0.00"

    static List<String> returnLog = new ArrayList<>();
    static Map<String, BigDecimal> refunds = new HashMap<>();

