import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;

public class CPTask22 {
    static class Position {
        final String symbol;
        BigDecimal quantity;
        final BigDecimal currentPrice;

        Position(String symbol, BigDecimal quantity, BigDecimal currentPrice) {
            this.symbol = symbol; this.quantity = quantity; this.currentPrice = currentPrice;
        }
        BigDecimal marketValue() { return quantity.multiply(currentPrice); }
    }

    static BigDecimal equity;
    static List<Position> positions = new ArrayList<>();
    static List<String> liquidationLog = new ArrayList<>();

    static void reset() { equity = BigDecimal.ZERO; positions.clear(); liquidationLog.clear(); }

    static BigDecimal totalMarketValue() {
        return positions.stream().map(Position::marketValue)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
    }

    // Margin ratio = equity / totalMarketValue (if totalMarketValue > 0)
    // Maintenance margin = 0.25 (25%)
    // If margin ratio < 0.25, must liquidate positions to restore it.
    //
    // Liquidation rules:
    //   1. Sort positions by market value DESCENDING (liquidate largest first)
    //   2. For each position, sell the MINIMUM whole units needed to bring margin ratio >= 0.25
    //      - Each unit sold: equity += currentPrice, quantity -= 1
    //   3. Log each sale as "LIQUIDATE:<symbol>:<unitsSold>"
    //   4. Stop as soon as margin ratio >= 0.25 (do NOT over-liquidate)
    // Returns: true if liquidation was needed, false otherwise
    static boolean checkAndLiquidate() {

