        // DESIGN: 10% of 100k = 10000, holdback 10% = 1000, disbursed = 9000
        String r1 = completeMilestone("DESIGN", true);
        assert r1.equals("DISBURSED") : r1;
        assert totalDisbursed.compareTo(new BigDecimal("9000.00")) == 0 : "d=" + totalDisbursed;
        assert holdback.compareTo(new BigDecimal("1000.00")) == 0 : "h=" + holdback;

        // Cannot skip to PILOT
        assert completeMilestone("PILOT", true).equals("WRONG_SEQUENCE");

        // PROTOTYPE: 25% = 25000, holdback 10% = 2500, disbursed = 22500
        completeMilestone("PROTOTYPE", true);
        assert totalDisbursed.compareTo(new BigDecimal("31500.00")) == 0 : "d=" + totalDisbursed;
